-- The Cape of Stranglethorn: creature abilities
-- Most of the zone's creatures (the Bloodsail and Booty Bay pirates, the Venture Co., the Bloodscalp and Skullsplitter trolls, the naga, crocolisks, apes and
-- basilisks of the Cape and Stranglethorn Vale) had no AI or ran classic rows. Port their abilities from the
-- Cataclysm data, and from the classic data where Cataclysm has none, keeping the quest scripts already in place; gossip and quest
-- reward scripts of the references are left out. The creatures no reference scripts cast their sniffed spells (creature_template
-- spell1-8).

SET @ENTRIES := '588,595,667,669,670,674,676,677,681,682,683,684,685,687,689,699,729,730,736,772,782,905,1094,1144,1488,1489,1490,1491,1492,1493,1511,1514,1516,1550,1557,1558,1562,1653,1713,1907,2521,2522,2535,2541,2544,2545,2551,2635,4457,4505,4506,5434,14491,14492,43219,43223,43364,43376,43377,43417,43454,43536,43542,43553,43605,43636,43659,43660,43716,43726,43760,44113';

UPDATE `creature_template` SET `AIName` = 'SmartAI' WHERE FIND_IN_SET(`entry`, @ENTRIES);
DELETE FROM `smart_scripts` WHERE `source_type` = 0 AND FIND_IN_SET(`entryorguid`, @ENTRIES);

-- Creatures without reference data: their sniffed creature_template spell1-8
SET @ENTRIES := '15088,43050,51534,51661,51663,51823,52224,52372,52982';

UPDATE `creature_template` SET `AIName` = 'SmartAI' WHERE FIND_IN_SET(`entry`, @ENTRIES);
DELETE FROM `smart_scripts` WHERE `source_type` = 0 AND FIND_IN_SET(`entryorguid`, @ENTRIES);
